def is_undulating(n):
    """
    Check if a number is undulating, meaning its digits alternate strictly between higher and lower values.
    For example, 121 (1 < 2 > 1) or 12321 (1 < 2 > 3 < 2 > 1) are undulating, but 1212121 (1 < 2 > 1 < 2 > 1 < 2 > 1) is not considered strictly alternating.
    """
    if n < 10:
        return False  # Single digit numbers cannot be undulating

    digits = [int(d) for d in str(n)]
    length = len(digits)

    # Check if the sequence alternates strictly between increasing and decreasing
    for i in range(1, length):
        # Check if the direction changes more than expected (i.e., not strictly alternating)
        if i % 2 == 1:
            if digits[i] <= digits[i-1]:
                return False
        else:
            if digits[i] >= digits[i-1]:
                return False

    return True
