def is_majority(arr, n, x):
    # The array is sorted, so we can find the first and last occurrence of x using binary search.
    def binary_search_first(arr, x):
        left, right = 0, n - 1
        first = -1
        while left <= right:
            mid = (left + right) // 2
            if arr[mid] == x:
                first = mid
                right = mid - 1
            elif arr[mid] < x:
                left = mid + 1
            else:
                right = mid - 1
        return first

    def binary_search_last(arr, x):
        left, right = 0, n - 1
        last = -1
        while left <= right:
            mid = (left + right) // 2
            if arr[mid] == x:
                last = mid
                left = mid + 1
            elif arr[mid] < x:
                left = mid + 1
            else:
                right = mid - 1
        return last

    first_occurrence = binary_search_first(arr, x)
    if first_occurrence == -1:
        return False  # x not found in the array

    last_occurrence = binary_search_last(arr, x)
    count = last_occurrence - first_occurrence + 1

    return count > n // 2
