def otherside_rightangle(w, h):
    """
    Calculate the length of the hypotenuse or the remaining side of a right-angled triangle.
    If either w or h is the hypotenuse, the function will compute the other side.
    Otherwise, it will compute the hypotenuse.

    :param w: length of one side or the hypotenuse
    :param h: length of another side or the hypotenuse
    :return: length of the remaining side
