    # Check if w and h are both legs (use Pythagorean theorem)
    if (w * w + h * h) > max(w, h) ** 2:
        return math.sqrt(w * w + h * h)
    else:
        # If one of them is the hypotenuse, compute the other side
        if w > h:
            return math.sqrt(w * w - h * h)
        else:
            return math.sqrt(h * h - w * w)
